import { chromium } from 'playwright';
import jwt from 'jsonwebtoken';

const token = jwt.sign(
  { userId: 22, email: 'test@merchant.com', merchantId: 22, role: 'merchant' },
  'dev-only-jwt-secret-not-for-production',
  { expiresIn: '2h' }
);

const browser = await chromium.launch({
  executablePath: '/nix/store/zi4f80l169xlmivz8vja8wlphq74qqk0-chromium-125.0.6422.141/bin/chromium',
});

for (const w of [430, 1280]) {
  const ctx = await browser.newContext({ viewport: { width: w, height: 900 } });
  await ctx.addInitScript((t) => localStorage.setItem('authToken', t), token);
  const page = await ctx.newPage();
  await page.goto('http://localhost:5000/stock', { waitUntil: 'networkidle' });
  await page.waitForTimeout(1500);
  // Sample the far-left gutter pixel color at 1280 to confirm white
  const bg = await page.evaluate(() => {
    const el = document.elementFromPoint(5, 400);
    return el ? getComputedStyle(el).backgroundColor : 'none';
  });
  console.log(`w=${w} leftGutterBg=${bg}`);
  await page.screenshot({ path: `/tmp/claude-1000/-home-runner-workspace/042e8618-6ba0-4b84-814b-f08a70d545f7/scratchpad/stock-${w}.png`, fullPage: false });
  await ctx.close();
}
await browser.close();

