200	  const byNewest = (a: any, b: any) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
201	  const todayInvoices = filtered.filter((i: any) => new Date(i.createdAt) >= today).sort(byNewest);
202	  const yesterdayInvoices = filtered.filter((i: any) => new Date(i.createdAt) >= yesterday && new Date(i.createdAt) < today).sort(byNewest);
203	  // Everything else within the selected timeframe — previously dropped entirely,
204	  // which made "week/month/year" show an empty history. Capped for performance.
205	  const earlierInvoices = filtered.filter((i: any) => new Date(i.createdAt) < yesterday).sort(byNewest).slice(0, 50);
206	
207	  /* ── Freely slidable sheet state ──
208	     The sheet parks wherever the drag releases it — anywhere between fully
209	     covering the graph (0) and fully revealing it (defaultOffset). No snapping;
210	     only a spring back inside the bounds if the drag overshot them. */
211	  const topRef   = useRef<HTMLDivElement>(null);
212	  const sheetRef = useRef<HTMLDivElement>(null);
213	  const dragStartY   = useRef(0);
214	  const dragStartOff = useRef(0);
215	  const [measuredTop, setMeasuredTop] = useState<number | null>(null);
216	  const [sheetOffset, setSheetOffset] = useState<number | null>(null); // null = resting at default
217	  const [dragging, setDragging] = useState(false);
218	
219	  // Track the dark top section's height — that's the "fully revealed" position.
220	  useEffect(() => {
221	    const measure = () => {
222	      if (topRef.current) setMeasuredTop(topRef.current.offsetHeight + 12);
223	    };
224	    measure();
225	    const ro = new ResizeObserver(measure);
226	    if (topRef.current) ro.observe(topRef.current);
227	    return () => ro.disconnect();
228	  }, []);
229	
230	  const defaultOffset = measuredTop ?? 320;
231	  const currentOffset = sheetOffset ?? defaultOffset;
232	
233	  const onDragStart = useCallback((e: React.PointerEvent) => {
234	    e.currentTarget.setPointerCapture(e.pointerId);
235	    dragStartY.current   = e.clientY;
236	    dragStartOff.current = currentOffset;
237	    setDragging(true);
238	  }, [currentOffset]);
239	
240	  const onDragMove = useCallback((e: React.PointerEvent) => {
