import { chromium } from 'playwright';
import jwt from 'jsonwebtoken';

const token = jwt.sign(
  { userId: 22, email: 'test@merchant.com', merchantId: 22, role: 'merchant' },
  process.env.JWT_SECRET,
  { expiresIn: '2h' }
);

const browser = await chromium.launch({
  executablePath: '/nix/store/zi4f80l169xlmivz8vja8wlphq74qqk0-chromium-125.0.6422.141/bin/chromium',
});

async function testDrag(path, label) {
  const ctx = await browser.newContext({ viewport: { width: 430, height: 900 } });
  await ctx.addInitScript((t) => localStorage.setItem('authToken', t), token);
  const page = await ctx.newPage();
  await page.goto(`http://localhost:5000${path}`, { waitUntil: 'networkidle' });
  await page.waitForTimeout(1800);

  // The sheet is the element whose transform is translateY(...). Grab the handle (5px tall pill inside 50px handle bar).
  // Read sheet transform at rest.
  const getSheetY = () => page.evaluate(() => {
    // find element with borderRadius '32px 32px 0 0' and a translateY transform
    const els = [...document.querySelectorAll('div')];
    const sheet = els.find(e => {
      const s = getComputedStyle(e);
      return s.borderTopLeftRadius === '32px' && s.transform && s.transform !== 'none';
    });
    if (!sheet) return null;
    const m = getComputedStyle(sheet).transform.match(/matrix\([^)]+\)/);
    if (!m) return null;
    const parts = getComputedStyle(sheet).transform.replace(/matrix\(|\)/g,'').split(',').map(Number);
    return parts[5]; // ty
  });

  const restY = await getSheetY();

  // Locate the handle bar center: it's near top of the sheet at restY + ~25
  // Drag with the mouse from that point upward by 120px (partial, not to full).
  const box = await page.evaluate((ry) => ry, restY);
  const startX = 215;
  const startY = Math.round(restY + 25);
  await page.mouse.move(startX, startY);
  await page.mouse.down();
  await page.mouse.move(startX, startY - 60, { steps: 8 });
  await page.mouse.move(startX, startY - 120, { steps: 8 });
  await page.mouse.up();
  await page.waitForTimeout(600);

  const afterY = await getSheetY();
  const moved = restY - afterY;
  // free-park: afterY should be roughly restY-120 (partial), NOT snapped to 0 or restY
  const freeParked = afterY > 5 && afterY < restY - 20;
  console.log(`${label}: restY=${restY?.toFixed(0)} afterY=${afterY?.toFixed(0)} moved=${moved?.toFixed(0)}px freeParked(mouse)=${freeParked}`);
  await ctx.close();
}

await testDrag('/transactions', 'transactions');
await testDrag('/trades/analytics', 'trades-analytics');
await browser.close();

