import jwt from 'jsonwebtoken';

const SECRET = process.env.JWT_SECRET;
const token = jwt.sign({ userId: 22, email: 'test@merchant.com', merchantId: 22, role: 'merchant' }, SECRET, { expiresIn: '1h' });
const H = { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' };
const BASE = 'http://localhost:5000';

// 1. Find a completed, not-yet-refunded transaction for merchant 22
const txs = await (await fetch(`${BASE}/api/merchants/22/transactions`, { headers: H })).json();
const list = Array.isArray(txs) ? txs : (txs.transactions || []);
const cand = list.find(t => t.status === 'completed' &&
  (parseFloat(t.refundableAmount ?? t.price) === parseFloat(t.price)) &&
  parseFloat(t.price) > 0);
if (!cand) { console.log('No clean completed txn found among', list.length, 'txns. Statuses:', [...new Set(list.map(t=>t.status))]); process.exit(0); }

const price = parseFloat(cand.price);
console.log(`Target txn #${cand.id}: price=$${price.toFixed(2)} status=${cand.status} refundable=${cand.refundableAmount ?? '(null)'}`);

// 2. Fire TWO concurrent full-amount refunds
const body = JSON.stringify({ refundAmount: price.toFixed(2), refundReason: 'concurrency-test', refundMethod: 'card' });
const [r1, r2] = await Promise.all([
  fetch(`${BASE}/api/transactions/${cand.id}/refunds`, { method: 'POST', headers: H, body }),
  fetch(`${BASE}/api/transactions/${cand.id}/refunds`, { method: 'POST', headers: H, body }),
]);
console.log(`concurrent refund results: [${r1.status}, ${r2.status}]  (expect exactly one 200 and one 409)`);

// 3. Verify final state — totalRefunded must equal price exactly (NOT 2x)
const after = await (await fetch(`${BASE}/api/transactions/${cand.id}`, { headers: H })).json();
console.log(`AFTER: status=${after.status} totalRefunded=$${after.totalRefunded} refundableAmount=$${after.refundableAmount} price=$${after.price}`);
const totalRef = parseFloat(after.totalRefunded);
const ok = Math.abs(totalRef - price) < 0.005 && parseFloat(after.refundableAmount) < 0.005;
const successes = [r1.status, r2.status].filter(s => s === 200).length;
console.log(`\nRESULT: ${(successes === 1 && ok) ? 'PASS ✓ — exactly one refund applied, totalRefunded==price (no double-refund)' : 'FAIL ✗ — successes='+successes+' totalRefunded='+totalRef+' price='+price}`);

