import { chromium } from 'playwright';
import jwt from 'jsonwebtoken';

const token = jwt.sign({ userId: 22, email: 'test@merchant.com', merchantId: 22, role: 'merchant' }, process.env.JWT_SECRET, { expiresIn: '1h' });
const browser = await chromium.launch({ executablePath: '/nix/store/zi4f80l169xlmivz8vja8wlphq74qqk0-chromium-125.0.6422.141/bin/chromium' });

// Authed merchant routes + the PUBLIC payment page (validates C1 sanitizer didn't break branding)
const authed = ['/dashboard', '/transactions', '/settings', '/stock', '/property/analytics', '/trades/analytics'];
const publicRoutes = ['/pay/22'];

async function sweep(path, withAuth) {
  const ctx = await browser.newContext({ viewport: { width: 430, height: 900 } });
  if (withAuth) await ctx.addInitScript((t) => { localStorage.setItem('authToken', t); localStorage.setItem('merchantId', '22'); }, token);
  const page = await ctx.newPage();
  const errors = [];
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text().slice(0, 140)); });
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message.slice(0, 140)));
  const failed = [];
  page.on('requestfailed', r => failed.push(r.url().replace('http://localhost:5000','').slice(0, 80)));
  page.on('response', r => { if (r.url().includes('/api/') && r.status() >= 500) failed.push(`${r.status()} ${r.url().replace('http://localhost:5000','').slice(0,60)}`); });
  try {
    await page.goto(`http://localhost:5000${path}`, { waitUntil: 'networkidle', timeout: 15000 });
    await page.waitForTimeout(1200);
  } catch (e) { errors.push('NAV: ' + e.message.slice(0, 80)); }
  const bodyLen = (await page.evaluate(() => document.body?.innerText?.length || 0));
  const realErrors = errors.filter(e => !/favicon|ResizeObserver|Download the React DevTools/i.test(e));
  console.log(`${withAuth?'🔒':'🌐'} ${path.padEnd(22)} text=${String(bodyLen).padStart(5)}  errs=${realErrors.length}  5xx/failed=${failed.length}`);
  realErrors.slice(0, 3).forEach(e => console.log('      ⚠ ' + e));
  failed.slice(0, 3).forEach(f => console.log('      ✗ ' + f));
  await ctx.close();
}

console.log('=== headless route sweep @430px (post-fix regression check) ===');
for (const p of authed) await sweep(p, true);
for (const p of publicRoutes) await sweep(p, false);
await browser.close();

