import jwt from 'jsonwebtoken';
const SECRET = process.env.JWT_SECRET;
const token = jwt.sign({ userId: 22, email: 'test@merchant.com', merchantId: 22, role: 'merchant' }, SECRET, { expiresIn: '1h' });
const BASE = 'http://localhost:5000';
const SENSITIVE = ['windcaveFeeRate', 'platformFeeRate', 'merchantNet'];

async function openStream(label, url) {
  const res = await fetch(url, { headers: { Accept: 'text/event-stream' } });
  const reader = res.body.getReader();
  const dec = new TextDecoder();
  const events = [];
  (async () => {
    let buf = '';
    while (true) {
      const { value, done } = await reader.read();
      if (done) break;
      buf += dec.decode(value, { stream: true });
      let idx;
      while ((idx = buf.indexOf('\n\n')) >= 0) {
        const frame = buf.slice(0, idx); buf = buf.slice(idx + 2);
        const m = frame.match(/^data: (.*)$/s);
        if (m) { try { events.push(JSON.parse(m[1])); } catch {} }
      }
    }
  })();
  return { label, events, close: () => reader.cancel().catch(() => {}) };
}

const anon = await openStream('anonymous', `${BASE}/api/merchants/22/events`);
const authed = await openStream('authed', `${BASE}/api/merchants/22/events?token=${encodeURIComponent(token)}`);
await new Promise(r => setTimeout(r, 800)); // let both connect

// Trigger a broadcast: create a transaction for merchant 22
const create = await fetch(`${BASE}/api/transactions`, {
  method: 'POST', headers: { Authorization: `Bearer ${token}`, 'Content-Type': 'application/json' },
  body: JSON.stringify({ merchantId: 22, itemName: 'c3-redaction-test', price: '9.99' }),
});
console.log('create txn HTTP', create.status);
await new Promise(r => setTimeout(r, 1500)); // collect broadcast

function txnEvent(s) { return s.events.find(e => e.type === 'transaction_updated' && e.transaction); }
for (const s of [authed, anon]) {
  const ev = txnEvent(s);
  if (!ev) { console.log(`${s.label}: no transaction_updated event received (${s.events.map(e=>e.type).join(',')})`); continue; }
  const present = SENSITIVE.filter(f => f in ev.transaction);
  console.log(`${s.label.padEnd(10)}: sensitive fields present = [${present.join(', ') || 'NONE'}]  (id=${ev.transaction.id}, price=${ev.transaction.price}, status=${ev.transaction.status})`);
}
const a = txnEvent(authed), n = txnEvent(anon);
const pass = a && n && SENSITIVE.some(f => f in a.transaction) && SENSITIVE.every(f => !(f in n.transaction));
console.log(`\nRESULT: ${pass ? 'PASS ✓ — authed sees fee internals, anonymous does NOT' : 'FAIL ✗ (authed has='+(a?SENSITIVE.filter(f=>f in a.transaction):'-')+' anon has='+(n?SENSITIVE.filter(f=>f in n.transaction):'-')+')'}`);
anon.close(); authed.close();
process.exit(0);

